import { VoucherItemDTO } from '~/entities/voucher/api/dtos/voucher-item';
import { IssueVoucherStatusCd } from '~/shared/api/dtos/enums';
import { MAX_INPUT_NUMBER } from '~/shared/constants/form';
import i18n from '~/shared/i18n/i18n';
import { useVoucherNavigation } from '~/shared/lib/hooks/use-navigate';
import { parseToDate } from '~/shared/lib/web-view-bridge';

export const VoucherItem = ({ item }: { item: VoucherItemDTO }) => {
  const { navigateToVoucherDetail } = useVoucherNavigation();

  const handleClick = () => {
    if (!item?.vouchId) return false;
    navigateToVoucherDetail(item.vouchId, item);
  };
  const useFormattedAmount = (num?: string | number | null): string => {
    if (num === null || num === undefined || isNaN(Number(num))) return '';
    const numAmt = Number(num);
    if (numAmt > MAX_INPUT_NUMBER) {
      return MAX_INPUT_NUMBER.toLocaleString();
    }
    return numAmt.toLocaleString();
  };

  return (
    <div onClick={() => handleClick()} className="flex w-full flex-col">
      <div className={`vouc-box ${item.isuVouchSttusCd === IssueVoucherStatusCd.이용자사용중 ? '' : 'exp'}`}>
        <div className="vouc-box-top">
          <p>{item.vouchNm}</p>
          <span className="vouc-type cashback">{item.vouchTyNm}</span>
        </div>
        <div className="vouc-balance">
          <p>{i18n.t('holdingBalance')}</p>
          <p>
            {useFormattedAmount(item.pbmBalanceOf ?? 0)} {i18n.t('won')}
          </p>
        </div>
        <span className="vouc-lmit">
          {parseToDate(item.rcvfverUseStartDt, 'yyyy.MM.dd') + ' ~ ' + parseToDate(item.rcvfverUseEndDt, 'yyyy.MM.dd')}
          {item.isuVouchSttusCd === IssueVoucherStatusCd.이용자사용중 ? '' : ` (${item.vouchProcStepNm})`}
        </span>
      </div>
    </div>
  );
};
